<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response,Validator};use App\Repositories\{AcademicRepository,SettingsRepository,StudentRepository,WorkflowRepository,SupportRepository};use App\Services\{StudentService,CredentialService};use App\Support\Flash;
final class StudentsController extends AdminPageController{
private function institute():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function repo():StudentRepository{return new StudentRepository($this->app->database());}private function admin():?Response{return can('students.view')?null:Response::html('Forbidden',403);}private function classes():array{return(new AcademicRepository($this->app->database()))->classes($this->institute());}private function fail(string$url,array$e,array$o):Response{$this->app->session()->flash('_errors',$e);$this->app->session()->flash('_old',$o);Flash::add('error',reset($e)[0]??'Please correct the form.');return Response::redirect(url($url));}
public function index(Request$r):Response{if($x=$this->admin())return$x;$q=trim((string)$r->query('student_search',''));$c=(int)$r->query('student_class',0);return$this->renderPage('students',['students'=>$this->repo()->paginate($this->institute(),$q,$c?:null),'classes'=>$this->classes(),'search'=>$q,'classFilter'=>$c]);}
public function create(Request$r):Response{if($x=$this->admin())return$x;return$this->renderPage('student-add',['classes'=>$this->classes(),'student'=>null,'documents'=>[]]);}
public function families(Request$r):Response{if($x=$this->admin())return$x;$q=trim((string)$r->query('search',''));return$this->renderPage('student-families',['students'=>$this->repo()->paginate($this->institute(),$q,null,100),'search'=>$q]);}
public function saveFamilies(Request$r):Response{if($x=$this->admin())return$x;$this->repo()->updateFamilies($this->institute(),(array)$r->input('families',[]));Flash::add('success','Student family assignments saved.');return Response::redirect(url('/admin/students/families'));}
public function statusManager(Request$r):Response{if($x=$this->admin())return$x;$q=trim((string)$r->query('search',''));return$this->renderPage('student-status',['students'=>$this->repo()->paginate($this->institute(),$q,null,100),'search'=>$q]);}
public function bulkStatus(Request$r):Response{if($x=$this->admin())return$x;$status=(string)$r->input('status');if(!in_array($status,['active','inactive'],true))return Response::html('Invalid status',422);$count=$this->repo()->setStatuses((array)$r->input('student_ids',[]),$this->institute(),$status);Flash::add($count?'success':'error',$count?$count.' student status record(s) updated.':'Select at least one student.');return Response::redirect(url('/admin/students/status'));}
public function store(Request$r):Response{if($x=$this->admin())return$x;return$this->save($r,null);}
public function show(Request$r):Response{if($x=$this->admin())return$x;$s=$this->repo()->find((int)$r->route('id'),$this->institute());return$s?$this->view('students/show',['student'=>$s,'pageTitle'=>'Student Details','pageDescription'=>'Student profile','activeMenu'=>'students','activeSubmenu'=>'students','styles'=>['css/variables.css','css/reset.css','css/base.css','css/layout.css','css/components.css?v=4','css/account-settings.css?v=1','css/settings.css?v=1','css/admin-pages.css?v=4','css/dashboard.css','css/responsive.css'],'scripts'=>['vendor/lucide.min.js','js/dropdowns.js','js/sidebar.js?v=4','js/app.js','js/admin-pages.js?v=4']]):Response::html('Student not found',404);}
public function edit(Request$r):Response{if($x=$this->admin())return$x;$s=$this->repo()->find((int)$r->route('id'),$this->institute());return$s?$this->renderPage('student-add',['classes'=>$this->classes(),'student'=>$s,'documents'=>$this->repo()->documents((int)$s['id'],$this->institute())]):Response::html('Student not found',404);}
public function update(Request$r):Response{if($x=$this->admin())return$x;return$this->save($r,(int)$r->route('id'));}
private function save(Request$r,?int$id):Response{$data=$r->all();$v=new Validator();$rules=['studentname'=>'required|max:160','reg'=>'required|max:80','doa'=>'required|date','class'=>'required|integer','student_fee'=>'numeric|min:0','discount_type'=>'required|in:percentage,fixed','discount'=>'required|numeric|min:0','dob'=>'date','fi'=>'numeric|min:0','mi'=>'numeric|min:0','noc'=>'integer|min:0'];$back=$id?'/admin/students/'.$id.'/edit':'/admin/students/create';if(!$v->validate($data,$rules))return$this->fail($back,$v->errors(),$data);if(!$this->repo()->classIsValid((int)$data['class'],$this->institute()))return$this->fail($back,['class'=>['Select a valid class.']],$data);$service=new StudentService($this->repo());$picture=$service->storeImage($r->file('fileToUpload'));if($picture===false)return$this->fail($back,['fileToUpload'=>['Picture must be JPG/PNG and no larger than 100KB.']],$data);$uploads=[];foreach(['birth_certificate'=>'Birth certificate / B-Form','previous_school_document'=>'Previous school record','guardian_cnic_document'=>'Parent / guardian CNIC','other_document'=>'Other document']as$key=>$type){$doc=$service->storeDocument($r->file($key),$type);if($doc===false){foreach($uploads as$u)@unlink(BASE_PATH.'/public/'.$u['file_path']);return$this->fail($back,[$key=>['Documents must be PDF, JPG or PNG and no larger than 5MB.']],$data);}if($doc)$uploads[]=$doc;}$old=$id?$this->repo()->find($id,$this->institute()):null;if($id&&!$old)return Response::html('Student not found',404);try{$mapped=$service->data($data,$this->institute(),$picture);if($id){$service->update($id,$this->institute(),$mapped);if($picture&&!empty($old['picture_path']))@unlink(BASE_PATH.'/public/'.$old['picture_path']);Flash::add('success','Student updated.');}else{$id=$service->create($mapped);Flash::add('success','Student created.');}foreach($uploads as$doc)$this->repo()->addDocument($doc+['student_id'=>$id,'uploaded_by'=>(int)user()['id'],'created_at'=>date('Y-m-d H:i:s')]);}catch(\PDOException$e){if($picture)@unlink(BASE_PATH.'/public/'.$picture);foreach($uploads as$u)@unlink(BASE_PATH.'/public/'.$u['file_path']);return$this->fail($back,['reg'=>['Registration number already exists.']],$data);}return Response::redirect(url('/admin/students/'.$id));}
public function status(Request$r):Response{if($x=$this->admin())return$x;$status=(string)$r->input('status');if(!in_array($status,['active','inactive'],true))return Response::html('Invalid status',422);if(!$this->repo()->setStatus((int)$r->route('id'),$this->institute(),$status))return Response::html('Student not found',404);Flash::add('success','Student status updated.');return Response::redirect(url('/admin/students'));}
public function delete(Request$r):Response{if($x=$this->admin())return$x;$result=$this->repo()->deleteStudent((int)$r->route('id'),$this->institute());if($result==='missing')return Response::html('Student not found',404);if($result==='in_use'){Flash::add('error','This student cannot be deleted while fee invoices exist.');return Response::redirect(url('/admin/students'));}Flash::add('success','Student deleted.');return Response::redirect(url('/admin/students'));}
public function bulkDelete(Request$r):Response{if($x=$this->admin())return$x;$result=$this->repo()->deleteStudents((array)$r->input('student_ids',[]),$this->institute());if($result['deleted'])Flash::add('success',$result['deleted'].' student(s) deleted.');if($result['blocked'])Flash::add('error',$result['blocked'].' student(s) could not be deleted because fee invoices exist.');if(!$result['deleted']&&!$result['blocked'])Flash::add('error','Select at least one student to delete.');return Response::redirect(url('/admin/students'));}
public function admissionLetter(Request$r):Response{$q=trim((string)$r->query('q',''));$s=$this->repo()->find((int)$r->query('student_id',0),$this->institute());return$this->renderPage('student-admission-letter',['student'=>$s,'students'=>$this->repo()->paginate($this->institute(),$q,null,50),'search'=>$q,'institute'=>(new SettingsRepository($this->app->database()))->institute(),'rules'=>(new SettingsRepository($this->app->database()))->rules($this->institute())]);}public function idCards(Request$r):Response{$c=(int)$r->query('class',0);$q=trim((string)$r->query('search',''));return$this->renderPage('student-id-cards',['students'=>$this->repo()->paginate($this->institute(),$q,($c?:null),100),'classes'=>$this->classes(),'institute'=>(new SettingsRepository($this->app->database()))->institute(),'selectedClass'=>$c,'search'=>$q]);}public function basicList(Request$r):Response{$q=trim((string)$r->query('search',''));$c=(int)$r->query('class',0);$data=(new SupportRepository($this->app->database()))->students($this->institute(),$q,$c,(int)$r->query('page',1));return$this->renderPage('student-basic-list',['students'=>$data['rows'],'paginator'=>$data['paginator'],'classes'=>$this->classes(),'search'=>$q,'selectedClass'=>$c]);}public function logins(Request$r):Response{$accounts=(new SupportRepository($this->app->database()))->accounts('student',$this->institute());$credentials=new CredentialService($this->app->database());foreach($accounts as&$account)$account['visible_password']=$credentials->reveal($account['password_cipher']??null);unset($account);return$this->renderPage('student-logins',['accounts'=>$accounts,'temporaryCredential'=>$this->app->session()->pull('temporary_credential')]);}public function createLogin(Request$r):Response{try{$result=(new CredentialService($this->app->database()))->create('student',(int)$r->input('student_id'),$this->institute(),(string)$r->input('email'),(int)user()['id'],trim((string)$r->input('password'))?:null);}catch(\Throwable$e){Flash::add('error',$e->getMessage());return Response::redirect(url('/admin/students/logins'));}$this->app->session()->flash('temporary_credential',$result['temporary_password']);return Response::redirect(url('/admin/students/logins'));}public function promotions(Request$r):Response{$from=(int)$r->query('from_class',0);return$this->renderPage('student-promotions',['classes'=>$this->classes(),'selectedClass'=>$from,'students'=>$from?$this->repo()->paginate($this->institute(),'', $from,100):[],'history'=>(new SupportRepository($this->app->database()))->promotions($this->institute())]);}public function promote(Request$r):Response{try{(new WorkflowRepository($this->app->database()))->promote($this->institute(),(int)$r->input('from_class'),(int)$r->input('to_class'),(array)$r->input('students',[]),(int)user()['id']);}catch(\DomainException$e){return Response::html(e($e->getMessage()),422);}Flash::add('success','Students promoted.');return Response::redirect(url('/admin/students/promotions'));}public function reportCard(Request$r):Response{$exam=(int)$r->query('exam',0);$student=(int)$r->query('student',0);$w=new WorkflowRepository($this->app->database());return$this->renderPage('student-report-card',['exams'=>$w->exams($this->institute()),'students'=>$this->repo()->paginate($this->institute(),'',null,100),'result'=>$exam&&$student?$w->studentResult($this->institute(),$exam,$student):null,'selectedExam'=>$exam,'selectedStudent'=>$student]);}
}
